{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The prevalence, incidence and characteristics of bacterial infection in patients infected with severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2) is not well understood and has been raised as an important knowledge gap [6,7].",
      "reason": "The introduction describes the existing knowledge gap/uncertainty about the prevalence/incidence/characteristics of bacterial infection in SARS-CoV-2."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Understanding the proportion of COVID-19 patients with acute respiratory bacterial co-infection, and the culprit pathogens, is crucial for treating patients with COVID-19 and to help ensure responsible use of antibiotics and to minimize negative consequences of overuse [6]. In addition, this knowledge could have a signi fi cant impact in re fi ning empirical antibiotic management guidelines for patients with COVID-19. We performed a rapid review to determine the prevalence of bacterial infection in patients with COVID-19 and to identify the most common co-infecting respiratory organisms in these individuals.",
      "reason": "It explains why the review is needed (to inform treatment and responsible antibiotic use) and states the purpose of conducting the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_12",
      "quote": "To our knowledge, this is the fi rst living meta-analysis and systematic review focusing on bacterial co-infections in patients hospitalized for COVID-19; 24 studies were included.",
      "reason": "The manuscript claims novelty (“first living meta-analysis and systematic review”) but the evidence provided does not clearly describe how the need arises when similar reviews exist, nor does it explicitly identify/update/replicate specific prior systematic reviews with citations."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a prevalence/etiology-type systematic review (not an intervention effects review), so a proposed mechanism of action of an intervention is not applicable based on the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No complex intervention or delivery context is described in the retrieved evidence; therefore a logic model is not applicable."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Aims: To determine the prevalence of bacterial co-infection (at presentation) and secondary infection (after presentation) in patients with COVID-19.",
      "reason": "The review’s objective(s) are explicitly stated as an “Aims” statement in the abstract."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "We conducted a rapid systematic review guided by recommendations from the Cochrane Rapid Reviews Methods Group [10] to determine the prevalence of respiratory bacterial infections among individuals with con fi rmed active COVID-19 infection.",
      "reason": "The review question is about determining prevalence (not planned intervention effect comparisons), so PICO-based planned comparisons are not applicable."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "We included studies of humans with laboratory-con fi rmed SARS-CoV-2 infection across all healthcare settings (i.e. hospital, community, long-term care) and age groups (paediatric and adult patients). Bacterial infection was de fi ned as an acute infection including either (a) co-infection on presentation, or (b) secondary infection emerging during the course of illness or hospital stay. Cases where bacteria were detected in an isolate not from a respiratory tract or blood culture sample were excluded. We included randomized controlled trials, cohort studies and case series with more than 10 patients, but excluded reviews, editorials, letters and case studies.",
      "reason": "Eligibility for study characteristics is specified (population: lab-confirmed SARS-CoV-2; settings: hospital/community/long-term care; designs: RCT/cohort/case series >10; and follow-up timing is implicitly part of defining secondary infection). However, explicit follow-up requirements for eligibility are not reported."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "We performed a systematic search of MEDLINE, OVID Epub and EMBASE databases for published literature in the English language from January 1, 2019 to April 16, 2020",
      "reason": "Report characteristics are partially specified (English language; search date range). The evidence does not explicitly state dissemination year inclusion/exclusion beyond the search range, nor whether unpublished/ongoing/“report status” criteria were used."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_10",
      "quote": "The main reason for study exclusion was the lack of reporting of bacterial co-infection or bacterial secondary infection data (Fig. 1).",
      "reason": "The evidence provides one exclusion rationale (lack of reporting of outcome data) but does not distinguish exclusions due to outcomes not being measured versus outcomes not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Seven studies exclusively reported secondary bacterial infections, the remaining 17 studies were categorized as reporting bacterial co-infection. ... When strati fi ed by patient population (an estimate of COVID-19 illness severity), bacterial infection ranged from 5.9% (95%CI 3.8 e 8.0%) in all hospitalized patients to 8.1% in critically ill patients (95%CI 2.3 e 13.8) (Fig. 3).",
      "reason": "The review specifies synthesis grouping into bacterial co-infection vs secondary infection, and further stratifies by patient population/illness severity (all hospitalized vs critically ill)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Bacterial infection was de fi ned as an acute infection including either (a) co-infection on presentation, or (b) secondary infection emerging during the course of illness or hospital stay. Cases where bacteria were detected in an isolate not from a respiratory tract or blood culture sample were excluded. ... However, we excluded reviews, editorials, letters and case studies. ... we excluded studies that did not report data on bacterial infection or exclusively reported data on chronic co-infection or non-bacterial pathogens.",
      "reason": "Notable eligibility restrictions are accompanied by stated rationales (e.g., sample-source exclusions; excluding non-eligible publication types; excluding studies without bacterial infection data or focusing on chronic co-infection/non-bacterial pathogens)."
    }
  ],
  "confidence": 72
}

